function validate([s, p]) {
  if (s.length < 1 || s.length > 50) return 's needs 1 to 50 characters.';
  if (!/^[a-z]+$/.test(s)) return 's contains only lowercase English letters.';
  if (p.length < 1 || p.length > 50) return 'p needs 1 to 50 characters.';
  if (!/^[a-z]*\*[a-z]*$/.test(p)) return "p is lowercase letters with exactly one '*'.";
  return null;
}

