function hasMatch(s, p) {
  const star = p.indexOf('*');
  const prefix = p.slice(0, star);
  const suffix = p.slice(star + 1);
  const start = s.indexOf(prefix);
  if (start === -1) {
    return false;
  }
  return s.indexOf(suffix, start + prefix.length) !== -1;
}

