function hasMatch(s, p) {
  // Test every non-empty substring of s: it must begin with the part before the star and end with
  // the part after it, without the two parts overlapping.
  const [before, after] = p.split('*');
  for (let i = 0; i < s.length; i++) {
    for (let j = i + 1; j <= s.length; j++) {
      const piece = s.slice(i, j);
      if (piece.length >= before.length + after.length && piece.startsWith(before) && piece.endsWith(after)) return true;
    }
  }
  return false;
}

