function generate(rand, size) {
  const large = size === 'large';
  const pick = (k) => Math.floor(rand() * k);
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.slice(0, large ? 2 + pick(3) : 1 + pick(3));
  const word = (length) => Array.from({ length }, () => alphabet[pick(alphabet.length)]).join('');
  const n = large ? 40 + pick(11) : 1 + pick(8);
  const longest = large ? 24 : 4;
  const s = word(n);
  let prefix;
  let suffix;
  if (rand() < 0.5) {
    // Both halves are copied from s, in either order, so matches are common but not certain.
    const piece = () => {
      const i = pick(n + 1);
      return s.slice(i, i + pick(Math.min(longest, n - i) + 1));
    };
    prefix = piece();
    suffix = piece();
  } else {
    prefix = word(pick(longest + 1));
    suffix = word(pick(longest + 1));
  }
  return [s, `${prefix}*${suffix}`];
}
